  vocab=[('extinct','no longer existing'),('endangered','in danger of becoming extinct'),('Arabian tahr','a wild mountain goat found in Oman'),('polar bear','a large white bear living in the Arctic'),('giant panda','a black and white bear from China that eats bamboo'),('sea ice','frozen sea water'),('Arctic','the area around the North Pole'),('adapt','change to live in new conditions')],
