L(id=2628, u='1', no=9, kind='Writing', title='Writing a report',
  target='revision of vocabulary and grammar; while, however', grammar='Contrasting ideas with while and however.',
  vocab=[('survey','asking many people the same questions'),('diagram','a picture that shows information'),('while','used in one sentence to contrast two ideas'),('however','used at the start of a new sentence to contrast'),('paragraph','a group of sentences about one idea')],
  aims=['Write a report about a survey.','Use while and however to contrast ideas.','Plan a report using diagrams.'],
  start='Students write as many environment words as they can in one minute (stopwatch).',
  tasks1=['Task 1: Look at the diagrams – are they a helpful way to present information?','Task 2: Read the How to write… box; match the paragraphs of the report with the descriptions.','Explain while (same sentence) and however (new sentence).','Task 3: Write a report on a survey about endangered animals.'],
  tasks2=['Task 1: Complete the sentences with while or however (Writing tip).','Task 2: Look at the diagrams and answer the questions.','Task 3: Study the two diagrams and plan a report about the survey results; compare plans with a partner.'],
  cb='29', ab='21–22', finish='Students write in their Learning diary: Today I wrote a report about … .', hwk='Photocopiable 25.',
  hw=('Join with "while": I like swimming. My friend likes running.','I like swimming while my friend likes running.','Rewrite with "However": Many students recycle. Some students don\'t.','Many students recycle. However, some students don\'t.'),
  bank=['m: Gم|I like swimming ______ my best friend likes running.|while|however|so',
        'm: Gم|Many students recycle. ______, some students throw everything away.|However|While|Because',
        'm: Gم|60% of students walk to school, ______ 40% come by bus.|while|however|because of',
        'm: Vن|Asking many people the same questions is a ______.|survey|diagram|diary',
        'm: Vن|A picture that shows information is a ______.|diagram|paragraph|poem',
        'm: Vم|A report should have a clear ______ at the top.|title|ending|signature',
        'm: Gن|Most students ______ that pandas are their favourite animal.|said|says|saying',
        'm: Rم|Survey results: 30 students answered. 18 students said the polar bear needs most help, while 12 chose the giant panda. // How many students chose the giant panda?|12|18|30',
        'w: Rن1|We use "however" at the start of a new sentence and "while" in the same sentence. // Statement: "While" always starts a new sentence. (True or False?) => False',
        'w: Gم1|Complete with while or however: Ali likes football ______ his brother prefers tennis. => while',
        'l: Wم5|Write a short report (about 60 words) about a class survey: "How do students come to school?" Use while and however. => Title and introduction ;; Results with numbers ;; while and however used correctly ;; Conclusion ;; About 60 words'],
  study=dict(intro='In this lesson you learn how to write a report about a survey and how to contrast ideas with while and however.',
   O=[('Organise a report.',['Title.','Introduction: what the survey was about.','Results: numbers from the diagrams.','Conclusion.']),('Contrast ideas.',['while – in the same sentence: I like swimming while my friend likes running.','However – at the start of a new sentence, with a comma.'])],
   R=['However, + comma.','Use numbers and percentages from the diagram.'],
   simple='while = same sentence.\nHowever, = new sentence.\nReport: title → introduction → results → conclusion.',
   F=[('I like tea ______ my sister likes coffee.','while'),('It was cold. ______, we went out.','However'),('Asking many people questions = a s______','survey')],
   C=[('(While / However) starts a new sentence.','However'),('A report needs a (title / greeting).','title'),('Diagrams show (information / feelings).','information')],
   S=[('What are the parts of a report?','title, introduction, results, conclusion'),('Write a sentence with "while".','e.g. Ali walks to school while Saif comes by bus.'),('What is a survey?','asking many people the same questions')]),
  games=dict(claims=[('"However" usually starts a new sentence.',True,'It is followed by a comma.'),('A report has no title.',False,'It needs a clear title.'),('"While" can join two contrasting ideas in one sentence.',True,'I like X while he likes Y.'),('Surveys ask only one person.',False,'They ask many people.')],
   links=[('Survey','Diagram','We show the results in a diagram.'),('Two different ideas','while / however','We contrast them.')],
   seq=('Writing a report',['Write a title','Write an introduction','Give the results','Write a conclusion','Check your work'])),
  cando=['أكتب تقريرًا عن نتائج استبيان مستعينًا بالرسوم البيانية.','أربط بين فكرتين متضادتين باستخدام while و however.','أخطط لتقريري وأقارن خطتي بخطة زميلي.'])

