L(id=2631, u='2', no=2, kind='Dialogue', title='Safety in extreme sports',
  target='I suppose so. I told you so! Not really.', grammar=None,
  vocab=[('I suppose so.','I agree, but not strongly'),('I told you so!','I said this would happen'),('Not really.','No, not very much'),('injury','damage to the body'),('safety','being safe from danger'),('helmet','a hard hat that protects your head')],
  aims=['Read and listen to a dialogue about safety in extreme sports.','Use the expressions I suppose so. I told you so! Not really.','Talk about staying safe.'],
  start='Play a Guessing game with pictures of extreme sports.',
  tasks1=['Write the expressions on the board; elicit when we use them.','Task 1: Listen and read – what do the boys disagree about? Discuss injuries and safety.','Task 2: In pairs, answer the questions.','Task 3: Find the expressions in the dialogue and act out short dialogues.'],
  tasks2=['Match sentence halves from the dialogue; listen and check.','Circle T or F and explain.','Complete the dialogues with the correct expressions (AB p.27).'],
  cb='43', ab='27', finish='Students discuss what they learned today and where they had difficulties.', hwk='Photocopiable T2.',
  hw=('Complete: A: Is surfing difficult? B: ______. It\'s quite easy.','Not really','When do we say "I told you so!"?','when something happens that we said would happen'),
  bank=['m: Vن|A: You should wear a helmet. B: ______. It\'s safer.|I suppose so|Not really|I told you so',
        'm: Vم|A: I fell off my bike! B: ______! I said it was dangerous.|I told you so|I suppose so|Not really',
        'm: Vم|A: Do you like horse riding? B: ______. I prefer swimming.|Not really|I told you so|Brilliant',
        'm: Vن|Always wear a ______ to protect your head.|helmet|scarf|jacket',
        'm: Vم|He had a bad ______ when he fell from the rock.|injury|safety|adventure',
        'm: Gن|You ______ wear a helmet when you go mountain biking.|should|shouldn\'t|needn\'t',
        'm: Gم|He ______ his leg when he was surfing.|hurt|hurts|hurting',
        'm: Gم|They ______ about safety when the teacher came in.|were talking|talked|talk',
        'w: Rن1|Sam: Let\'s go rock climbing without ropes. Yusuf: No way! It\'s too dangerous. We need ropes and helmets. // Statement: Yusuf wants to climb without ropes. (True or False?) => False',
        'w: Vن1|Complete: A: Is it cold today? B: Not ______. It\'s warm. => really',
        'l: Wم5|Write five safety rules (about 50 words) for a sport you like. => Five rules ;; Safety vocabulary ;; Modal verbs ;; Clear sentences ;; About 50 words'],
  study=dict(intro='In this lesson you read a dialogue about safety in extreme sports and learn useful conversation expressions.',
   O=[('Use conversation expressions.',['I suppose so. – I agree, but not strongly.','I told you so! – I said this would happen.','Not really. – No, not very much.']),('Talk about safety.',['wear a helmet, use ropes, follow the trainer, check the weather.'])],
   R=['"I told you so!" can sound rude – use it carefully.','Safety first in extreme sports.'],
   simple='Agree a little → I suppose so.\nSay no politely → Not really.\nIt happened as I said → I told you so!',
   F=[('A hard hat = a h______','helmet'),('Damage to the body = an i______','injury'),('A: Is it hard? B: Not ______.','really')],
   C=[('"Not really" means (no / yes).','no'),('Wear a helmet for (safety / injury).','safety'),('"I suppose so" means you (agree a little / disagree strongly).','agree a little')],
   S=[('What do the boys disagree about?','safety in extreme sports (whether to use safety equipment)'),('Give one safety rule for extreme sports.','wear a helmet / use ropes / go with a trainer'),('When do we say "I suppose so"?','when we agree but not strongly')]),
  games=dict(claims=[('"Not really" is a polite no.',True,'It means not very much.'),('A helmet protects your feet.',False,'It protects your head.'),('"I told you so!" means you predicted it.',True,'You said it would happen.'),('Safety equipment is not needed in extreme sports.',False,'It is very important.')],
   links=[('Helmet','Head safety','It protects your head.'),('Rope','Rock climbing safety','It stops you falling.')],
   seq=('Staying safe',['Learn the rules','Check the equipment','Wear a helmet','Follow the trainer'])),
  cando=['أقرأ حوارًا عن السلامة في الرياضات الخطرة وأجيب عن أسئلته.','أستخدم التعبيرات (I suppose so, I told you so!, Not really) في حوارات.','أكتب قواعد السلامة لرياضة أحبها.'])

L(id=2632, u='2', no=3, kind='Grammar', title='Reflexive pronouns',
  target='I fell when I was rock climbing and hurt myself. Did you do it yourself?', grammar='Reflexive pronouns: myself, yourself, himself, herself, itself, ourselves, yourselves, themselves.',
  vocab=[('reflexive pronoun','a pronoun ending in -self or -selves'),('hurt yourself','injure your own body'),('enjoy yourself','have a good time'),('by myself','alone, without help'),('teach yourself','learn something without a teacher')],
  aims=['Learn and use reflexive pronouns.','Understand a listening activity (choose the correct picture).'],
  start='Team game with Unit 2 flashcards (Extreme sports) on the board.',
  tasks1=['Task 1: Look back at the dialogue in Lesson 2 – are the sentences true or false?','Task 2: Study the grammar table; complete the rule.','Task 3: Underline reflexive pronouns in the dialogue.','Task 4: Say sentences using reflexive pronouns.','Task 5: Listen and choose the correct picture.','Task 6: Listen again and answer the questions.'],
  tasks2=['Elicit when we use reflexive pronouns (subject = object; end in -self/-selves).','Activity Book grammar practice (AB pp.28–29) and Grammar practice p.61.'],
  cb='44–45', ab='28–29, 61', finish='Ask: Did you enjoy yourself today? What did you teach yourself? Check confidence with the new grammar.', hwk='Grammar practice T1 and T2, AB p.61.',
  hw=('Complete: She taught ______ to swim.','herself','Complete: We enjoyed ______ at the camp.','ourselves'),
  bank=['m: Gن|I fell and hurt ______.|myself|me|my',
        'm: Gن|Did you make this cake ______?|yourself|yourselves|myself',
        'm: Gم|The children enjoyed ______ at the water park.|themselves|himself|ourselves',
        'm: Gم|My sister taught ______ to play the guitar.|herself|himself|itself',
        'm: Gم|We built the camp ______.|ourselves|themselves|yourself',
        'm: Gم|The cat washed ______ in the sun.|itself|himself|themselves',
        'm: Vم|"By myself" means ______.|alone|with friends|quickly',
        'm: Vم|"Enjoy yourself" means ______.|have a good time|hurt your leg|be careful',
        'w: Rن1|Omar went abseiling last week. He didn\'t hurt himself, but his friend Ali fell and hurt his arm. // Statement: Omar hurt himself. (True or False?) => False',
        'w: Gم1|Complete with ONE word: They looked at ______ in the mirror. => themselves',
        'l: Wم5|Write a short paragraph (about 50 words) about something you learned to do by yourself. Use reflexive pronouns. => What you learned ;; How you learned ;; At least two reflexive pronouns ;; Past simple ;; About 50 words'],
  study=dict(intro='In this lesson you learn reflexive pronouns and use them when the subject and the object are the same person.',
   O=[('Use reflexive pronouns.',['I → myself; you → yourself; he → himself; she → herself; it → itself.','we → ourselves; you → yourselves; they → themselves.']),('Know when to use them.',['When the subject and object are the same: I hurt myself.','For emphasis / alone: Did you do it yourself? I did it by myself.'])],
   R=['Singular ends in -self; plural ends in -selves.','himself (not hisself); themselves (not theirselves).'],
   simple='I hurt myself. She enjoyed herself. They taught themselves.',
   F=[('He hurt ______.','himself'),('We did it ______.','ourselves'),('They enjoyed ______.','themselves')],
   C=[('I made it (myself / me).','myself'),('She looked at (herself / himself).','herself'),('(Hisself / Himself) is correct.','Himself')],
   S=[('When do we use reflexive pronouns?','when the subject and the object are the same'),('Write a sentence with "yourself".','e.g. Did you paint this yourself?'),('What is the reflexive pronoun for "they"?','themselves')]),
  games=dict(claims=[('"I hurt myself" is correct.',True,'Subject = object.'),('"Theirselves" is a correct word.',False,'It is themselves.'),('Plural reflexive pronouns end in -selves.',True,'ourselves, yourselves, themselves.'),('"She enjoyed himself" is correct.',False,'She enjoyed herself.')],
   links=[('I','myself','Singular -self.'),('They','themselves','Plural -selves.')],
   seq=('Choosing a reflexive pronoun',['Find the subject','Is it singular or plural?','Add -self or -selves','Check the sentence'])),
  cando=['أستخدم الضمائر الانعكاسية (myself, herself, themselves…) استخدامًا صحيحًا.','أميّز متى يكون الفاعل والمفعول به شخصًا واحدًا.','أستمع إلى نص وأختار الصورة الصحيحة.'])

