L(id=2634, u='2', no=5, kind='Vocabulary and Grammar', title='Geography and the past perfect',
  target='north, south, east, west, sunrise, sunset, wood, field, valley, scenery, tide, bay; After they had eaten their breakfast, they looked in their guidebook.',
  grammar='Past perfect (had + past participle) for the earlier of two past actions.',
  vocab=[('valley','low land between hills or mountains'),('field','an area of land with grass or crops'),('wood','a small forest'),('scenery','the natural features of a place'),('tide','the rise and fall of the sea'),('bay','part of the sea with land around it'),('sunrise','the time when the sun comes up'),('sunset','the time when the sun goes down')],
  aims=['Learn and use words related to geography.','Learn and use the past perfect.'],
  start='Ask: What can you remember from the adventure story?',
  tasks1=['Pre-teach the compass directions (N, E, S, W).','Task 1: Match the geography words to the pictures; listen, check and repeat.','Task 2: Find the words in the story from Lesson 4.','Study the past perfect: After they had eaten their breakfast, they looked in their guidebook.','Practise sentences with after / before / when.'],
  tasks2=['Pair game: one student chooses a past event; the partner guesses what they had done before it with the past perfect.','Activity Book practice (AB pp.32–33).'],
  cb='48–49', ab='32–33', finish='Ask: What did you do after you had eaten breakfast this morning? Students answer in complete sentences.', hwk='Activity Book p.33.',
  hw=('Complete: After we ______ (finish) our homework, we went to the beach.','had finished','Name four compass directions.','north, south, east, west'),
  bank=['m: Gن|After they ______ breakfast, they looked in their guidebook.|had eaten|have eaten|eat',
        'm: Gم|When we arrived at the station, the train ______.|had left|has left|leaves',
        'm: Gم|She ______ never seen the sea before her trip to Salalah.|had|has|was',
        'm: Gم|I went to bed after I ______ my homework.|had finished|finish|was finishing',
        'm: Vن|The sun comes up at ______.|sunrise|sunset|tide',
        'm: Vن|Low land between two mountains is a ______.|valley|field|bay',
        'm: Vم|We watched the beautiful ______ from the top of Jebel Shams.|scenery|tide|field',
        'm: Vم|Part of the sea with land around it is a ______.|bay|wood|valley',
        'w: Rن1|After they had walked for two hours, the children reached a beautiful valley. They sat down and ate their lunch. // Statement: The children ate lunch before they started walking. (True or False?) => False',
        'w: Vن1|Complete: The opposite of north is ______. => south',
        'l: Wم5|Write a short paragraph (about 50 words) describing a beautiful place in Oman. Use geography words and one past perfect sentence. => Name and location ;; Geography vocabulary ;; One past perfect sentence ;; Description ;; About 50 words'],
  study=dict(intro='In this lesson you learn geography words and how to use the past perfect to show which past action happened first.',
   O=[('Use geography words.',['north, south, east, west; sunrise, sunset; wood, field, valley, scenery, tide, bay.']),('Use the past perfect.',['had + past participle.','The earlier action: After they had eaten breakfast, they looked in their guidebook.'])],
   R=['First action → past perfect; second action → past simple.','had + eaten, gone, seen, finished.'],
   simple='First: had + past participle.\nThen: past simple.\nAfter I had finished, I went out.',
   F=[('After she ______ (eat), she slept.','had eaten'),('The sun goes down at s______','sunset'),('A small forest = a w______','wood')],
   C=[('When I arrived, the film (had started / starts).','had started'),('A (valley / bay) is between mountains.','valley'),('I had (saw / seen) it before.','seen')],
   S=[('Write a past perfect sentence with "after".','e.g. After I had done my homework, I played football.'),('What is the tide?','the rise and fall of the sea'),('Name two geography words.','valley, field, bay, wood… (any two)')]),
  games=dict(claims=[('The past perfect uses had + past participle.',True,'had eaten, had gone.'),('A valley is part of the sea.',False,'It is low land between hills.'),('Sunrise is when the sun goes down.',False,'That is sunset.'),('The past perfect shows the earlier action.',True,'It happened first.')],
   links=[('Mountains','Valley','Low land between them.'),('Sea','Bay / tide','Geography of the coast.')],
   seq=('Making a past perfect sentence',['Find the first action','Use had + past participle','Add the second action','Use the past simple'])),
  cando=['أستخدم مفردات الجغرافيا والاتجاهات (valley, bay, north…) في وصف الأماكن.','أستخدم الماضي التام للتعبير عن الحدث الأسبق في الماضي.','أصف مكانًا جميلًا في عُمان.'])

