L(id=2644, u='3', no=5, kind='Vocabulary and Grammar', title='Imaginary situations and the second conditional',
  target='go into space, become a school principal, travel the world, donate to a charity, have a lot of money, have a wish, travel back in time, pass exams, be an inventor, become a book or film character',
  grammar='Second conditional (If + past simple, would + base verb) for imaginary situations.',
  vocab=[('donate to a charity','give money to an organisation that helps people'),('travel back in time','go to the past'),('inventor','a person who makes new things'),('principal','the head of a school'),('wish','something you want to happen'),('character','a person in a book or film')],
  aims=['Learn and use words for imaginary situations.','Learn and use the second conditional.'],
  start='Ask: What can you remember from the poem in Lesson 4?',
  tasks1=['Present the Unit 3 flashcards (Imaginary situations).','Task 1: Look and match; listen, check and repeat.','Task 2: Find the phrases in the poem.','Task 3: Study the second conditional; complete the rule.','Practise: If I had a lot of money, I would donate to a charity.'],
  tasks2=['Activity Book practice and Grammar practice.'],
  cb='74–75', ab='48–49', finish='Play Charades with imaginary situations (walking in space, being an inventor…).', hwk='Photocopiables 3 and 33.',
  hw=('Complete: If I ______ (have) a lot of money, I ______ (travel) the world.','had / would travel','Answer: What would you do if you became a school principal?','If I became a school principal, I would … (own answer)'),
  bank=['m: Gن|If I had a lot of money, I ______ donate to a charity.|would|will|am',
        'm: Gم|If I ______ an inventor, I would make a flying car.|were|am|will be',
        'm: Gم|If she could travel back in time, she ______ visit Ancient Egypt.|would|will|does',
        'm: Gم|What would you do if you ______ a wish?|had|have|will have',
        'm: Gم|If I ______ the principal, I would give students longer breaks.|were|am|be',
        'm: Vن|A person who makes new things is an ______.|inventor|principal|customer',
        'm: Vم|Giving money to help people is ______ to a charity.|donating|exchanging|refunding',
        'm: Vم|The head of a school is the school ______.|principal|inventor|character',
        'w: Rن1|If Hamad could become a film character, he would choose a superhero. He would use his powers to help people in danger. // Statement: Hamad would like to be a villain. (True or False?) => False',
        'w: Gم1|Complete with ONE word: If I ______ you, I would save your money. => were',
        'l: Wم5|Write a short paragraph (about 50 words): What would you do if you had a lot of money? Use the second conditional. => At least three second conditional sentences ;; Imaginary situation vocabulary ;; Reasons ;; Correct form ;; About 50 words'],
  study=dict(intro='In this lesson you learn phrases for imaginary situations and use the second conditional to talk about them.',
   O=[('Talk about imaginary situations.',['go into space, become a school principal, travel the world, donate to a charity.','have a lot of money, have a wish, travel back in time, be an inventor, become a book or film character.']),('Use the second conditional.',['If + past simple, would + base verb.','If I had a lot of money, I would travel the world.','If I were you … (were for all persons).'])],
   R=['Second conditional = imaginary or unlikely.','No "would" in the if-clause.'],
   simple='Imaginary: If I had wings, I would fly.\nIf + past, would + verb.',
   F=[('If I ______ (be) rich, I would help people.','were'),('If she had time, she ______ (learn) Chinese.','would learn'),('Give money to help = d______ to a charity','donate')],
   C=[('If I (had / have) a wish…','had'),('… I (would / will) go into space.','would'),('If I (were / was) you – formal choice','were')],
   S=[('When do we use the second conditional?','for imaginary or unlikely situations'),('Write a second conditional sentence.','e.g. If I could fly, I would visit every country.'),('What is an inventor?','a person who makes new things')]),
  games=dict(claims=[('The second conditional is for imaginary situations.',True,'If I had wings, I would fly.'),('"If I would have money" is correct.',False,'If I had money.'),('"If I were you" is correct.',True,'were is used for all persons.'),('A principal is a person in a film.',False,'It is the head of a school.')],
   links=[('A lot of money','Donate to a charity','A kind imaginary choice.'),('Time machine','Travel back in time','Go to the past.')],
   seq=('Making a second conditional',['Start with If','Use the past simple','Add a comma','Use would + base verb'])),
  cando=['أستخدم مفردات المواقف الخيالية (travel back in time, donate to a charity…).','أستخدم الجملة الشرطية الثانية للتعبير عن مواقف خيالية.','أتحدث عمّا سأفعله لو امتلكت أمنية.'])

